    "stream-live-send": {
        parameters: {
            query?: {
                /** @description Same as the Last-Event-ID header, for clients that reconnect by themselves */
                lastEventId?: string;
                /** @description The language the snapshots' words read in (en, vi); like Accept-Language, for clients that can't set headers */
                lang?: string;
            };
            header?: {
                /** @description Resume after this event id (the snapshot version) */
                "Last-Event-ID"?: string;
            };
            path: {
                /** @description Workspace slug */
                workspace: string;
                /** @description Campaign id */
                campaignId: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description OK */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/event-stream": ({
                        data: components["schemas"]["LiveHeartbeat"];
                        /**
                         * @description The event name.
                         * @constant
                         */
                        event: "heartbeat";
                        /** @description The event ID. */
                        id?: number | string;
                        /** @description The retry time in milliseconds. */
                        retry?: number;
                    } | {
                        data: components["schemas"]["LiveSnapshot"];
                        /**
                         * @description The event name.
                         * @constant
                         */
                        event: "snapshot";
                        /** @description The event ID. */
                        id?: number | string;
                        /** @description The retry time in milliseconds. */
                        retry?: number;
                    })[];
                };
            };
            /** @description Error */
            default: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
        };
    };
